	#[test]
	fn parses_exp() {
		let n = b"1";
		assert_eq!(
			NumInfo::parse(n, &NumInfoParseSettings::default()),
			(NumInfo { exponent: 0, sign: Sign::Positive }, 0..1)
		);
		let n = b"100";
		assert_eq!(
			NumInfo::parse(n, &NumInfoParseSettings::default()),
			(NumInfo { exponent: 2, sign: Sign::Positive }, 0..3)
		);
