		};
		const stripping = new Tokenizer(model);
		const floor = { excludeEncryptedReasoning: true };
		const estimate = stripping.countMessage(foreign, floor);
		expect(estimate).toBeGreaterThan(1000);
		expect(stripping.countMessage(foreign)).toBe(estimate);
		const replaying = new Tokenizer({ ...model, compat: { ...model.compat, stripThinkingHistory: false } });
		expect(replaying.countMessage(foreign, floor)).toBe(estimate);
	});

	test("counts only replayed content and recounts after the stripping policy changes", () => {
		const visible = { ...turn, content: [{ type: "text", text: "Done." }] } satisfies AssistantMessage;
		const agent = new Agent({ initialState: { model, systemPrompt: [], tools: [], messages: [] } });
		const floor = { excludeEncryptedReasoning: true };
		const visibleCount = agent.tokenizer.countMessage(visible);
		expect(agent.tokenizer.countMessage(turn)).toBe(visibleCount);
		expect(agent.tokenizer.countMessage(turn, floor)).toBe(visibleCount);

		const replaying = { ...model, compat: { ...model.compat, stripThinkingHistory: false } };
		expect(agent.tokenizer.countsAlike(replaying)).toBe(false);
		agent.setModel(replaying);
		expect(agent.tokenizer.countMessage(turn, floor)).toBeGreaterThan(visibleCount + 1000);
		expect(agent.tokenizer.countMessage(turn)).toBeGreaterThan(agent.tokenizer.countMessage(turn, floor));
		agent.setModel(model);
		expect(agent.tokenizer.countMessage(turn, floor)).toBe(visibleCount);
	});
});

// Contract: a chat-completions request without a reasoning slot drops the
// model's own past thinking, so the context estimate (and the compaction
// triggers built on it) must not count it; thinking the request carries still
// counts (#15797).
describe("chat-completions history estimate", () => {
	const THINKING = "Let me reason about the call sites carefully. ".repeat(400);
	const toolCall = { type: "toolCall", id: "call_1", name: "read", arguments: { path: "a.ts" } } as const;

	function completionsModel(
		id: string,
		compat: Partial<OpenAICompat> & { replayReasoningContent: boolean },
		reasoning = true,
	): Model<"openai-completions"> {
		return buildModel({
			id,
			name: id,
			api: "openai-completions",
			provider: "my-host",
			baseUrl: "http://my-server.example:8000/v1",
			reasoning,
			input: ["text"],
			cost: { input: 0, output: 0, cacheRead: 0, cacheWrite: 0 },
			contextWindow: 262_144,
			maxTokens: 32_768,
			compat: { thinkingFormat: "qwen-chat-template", ...compat },
		});
	}

	function thinkingTurn(from: Model, thinkingSignature: string): AssistantMessage {
		return {
			role: "assistant",
			content: [{ type: "thinking", thinking: THINKING, thinkingSignature }, toolCall],
			api: from.api,
			provider: from.provider,
			model: from.id,
			usage: {
				input: 100,
				output: 3_000,
				cacheRead: 0,
				cacheWrite: 0,
				totalTokens: 3_100,
				cost: { input: 0, output: 0, cacheRead: 0, cacheWrite: 0, total: 0 },
			},
			stopReason: "toolUse",
			timestamp: 1,
		};
	}

	const dropping = completionsModel("Qwen3.8-27B", { replayReasoningContent: false });
	const replaying = completionsModel("Qwen3.8-27B", { replayReasoningContent: true });
	const floor = { excludeEncryptedReasoning: true };
	const toolCallOnly = new Tokenizer(dropping).countMessage({ ...thinkingTurn(dropping, "x"), content: [toolCall] });

	test.each([
		{ name: "replay off", model: dropping, carried: false },
		{ name: "replay on", model: replaying, carried: true },
		{
			name: "replay only in the thinking view",
			model: completionsModel("Qwen3.8-27B", {
				replayReasoningContent: false,
				whenThinking: { replayReasoningContent: true },
			}),
			carried: true,
		},
		{
			name: "Mistral content parts",
			model: completionsModel("Qwen3.8-27B", { replayReasoningContent: false, mistralReasoningContentParts: true }),
			carried: true,
		},
		{
			name: "thinking as text",
			model: completionsModel("Qwen3.8-27B", { replayReasoningContent: false, requiresThinkingAsText: true }),
			carried: true,
		},
		{
			name: "reasoning content required for tool calls",
			model: completionsModel("Qwen3.8-27B", {
				replayReasoningContent: false,
				requiresReasoningContentForToolCalls: true,
			}),
			carried: true,
		},
		{
			name: "Z.AI on a reasoning model",
			model: completionsModel("Qwen3.8-27B", { replayReasoningContent: false, thinkingFormat: "zai" }),
			carried: true,
		},
		{
			name: "Z.AI on a non-reasoning model",
			model: completionsModel("Qwen3.8-27B", { replayReasoningContent: false, thinkingFormat: "zai" }, false),
			carried: false,
		},
		// Another model's thinking reaches the request demoted to text.
		{
			name: "another model's turn",
			model: dropping,
			from: completionsModel("other-model", { replayReasoningContent: false }),
			carried: true,
		},
		// LiteLLM replays a raw signature's thinking in `thinking_blocks`.
		{ name: "a raw LiteLLM signature", model: dropping, signature: "EqQBCkgIARABGAIiQL", carried: true },
	])("counts thinking only when a request carries it: $name", ({ model, from, signature, carried }) => {
		const turn = thinkingTurn(from ?? model, signature ?? "reasoning_content");
		const views = [model.compat, model.compat.whenThinking].filter(view => view !== undefined);
		const messages = transformMessages([turn], model);
		const sent = views.some(view =>
			JSON.stringify(convertMessages(model, { messages }, view)).includes(THINKING.trim()),
		);
		expect(sent).toBe(carried);

		const tokenizer = new Tokenizer(model);
		if (carried) {
			expect(tokenizer.countMessage(turn, floor)).toBeGreaterThan(toolCallOnly + 1000);
		} else {
			expect(tokenizer.countMessage(turn)).toBe(toolCallOnly);
			expect(tokenizer.countMessage(turn, floor)).toBe(toolCallOnly);
		}
	});

	test("recounts after the replay policy changes", () => {
		const turn = thinkingTurn(dropping, "reasoning_content");
		const agent = new Agent({ initialState: { model: dropping, systemPrompt: [], tools: [], messages: [] } });
		expect(agent.tokenizer.countMessage(turn, floor)).toBe(toolCallOnly);
		expect(agent.tokenizer.countsAlike(replaying)).toBe(false);
		agent.setModel(replaying);
		expect(agent.tokenizer.countMessage(turn, floor)).toBeGreaterThan(toolCallOnly + 1000);
	});
});

// Contract: a replayed signed thinking block costs what the reading model bills
// for it: Claude rebuilds the full reasoning from the signature and bills it at
// the size the turn billed as output; other readers are charged the
// signature's bytes.
describe("countMessage replayed thinking", () => {
	const SIGNATURE = "s".repeat(4000);
	const VISIBLE = "Check the call sites first.";
	// What the visible blocks count to in the test env (bytes/4 per fragment).
	const VISIBLE_TOKENS = 9;
	const OUTPUT_TOKENS = 3000;

	function reader(provider: "anthropic" | "openrouter" | "amazon-bedrock" | "google", id: string): Model {
		const model = getBundledModel(provider, id);
		if (!model) throw new Error(`missing bundled model ${provider}/${id}`);
		return model as Model;
	}

	function signedTurn(
		from: Pick<Model, "api" | "provider" | "id">,
		thinking: string,
		thinkingSignature?: string,
		stopReason: AssistantMessage["stopReason"] = "toolUse",
	): AssistantMessage {
		return {
			role: "assistant",
			content: [
				{ type: "thinking", thinking, thinkingSignature },
				{ type: "text", text: "Done." },
			],
			api: from.api,
			provider: from.provider,
			model: from.id,
			usage: {
				input: 100,
				output: OUTPUT_TOKENS,
				cacheRead: 0,
				cacheWrite: 0,
				totalTokens: 100 + OUTPUT_TOKENS,
				cost: { input: 0, output: 0, cacheRead: 0, cacheWrite: 0, total: 0 },
			},
			stopReason,
			timestamp: 1,
		};
	}

	const opus = reader("anthropic", "claude-opus-5-5");
	const bedrockOpus = reader("amazon-bedrock", "global.anthropic.claude-opus-5-5");
	const openRouterOpus = reader("openrouter", "~anthropic/claude-opus-latest");

	test.each([
		["on the Claude API", opus, opus, VISIBLE, "toolUse"],
		["on Bedrock", bedrockOpus, bedrockOpus, VISIBLE, "toolUse"],
		// Omitted display: no visible thinking, the same reasoning billed.
		["with its thinking omitted", opus, opus, "", "toolUse"],
		// The Claude API keeps another model's signature from the same deployment,
		// and Opus 5.5 reads Opus 5's thinking.
		[
			"from another Claude model on the same deployment",
			opus,
			reader("anthropic", "claude-opus-5"),
			VISIBLE,
			"toolUse",
		],
		// The thinking finished, signed, before the text hit max_tokens.
		["that stopped on length", opus, opus, VISIBLE, "length"],
		// The thinking finished, signed, before the abort cut the text short.
		["aborted after its thinking", opus, opus, VISIBLE, "aborted"],
	] as const)("charges a Claude turn replayed natively %s its output size", (_case, model, from, thinking, stop) => {
		expect(new Tokenizer(model).countMessage(signedTurn(from, thinking, SIGNATURE, stop))).toBe(OUTPUT_TOKENS);
	});

	test.each([
		// A signature is bound to the deployment that minted it.
		["a turn from another host", bedrockOpus, opus],
		// Bedrock binds it to the model too: another model's turn replays as text.
		[
			"another Claude model's turn on Bedrock",
			bedrockOpus,
			reader("amazon-bedrock", "global.anthropic.claude-opus-5"),
		],
		// OpenRouter filters reasoning history out of the request.
		["a reader that filters reasoning history", openRouterOpus, openRouterOpus],
	] as const)("charges only the visible blocks for %s, never the signature", (_case, model, from) => {
		expect(new Tokenizer(model).countMessage(signedTurn(from, VISIBLE, SIGNATURE))).toBe(VISIBLE_TOKENS);
	});

	test("charges only the visible thinking of an aborted turn's final, partly signed block", () => {
		// The replay drops that block's signature, so no reasoning rides along.
		const turn: AssistantMessage = {
			...signedTurn(opus, VISIBLE, SIGNATURE, "aborted"),
			content: [{ type: "thinking", thinking: VISIBLE, thinkingSignature: SIGNATURE }],
		};
		const tokenizer = new Tokenizer(opus);
		expect(tokenizer.countMessage(turn)).toBe(tokenizer.countMessage(turn, { excludeEncryptedReasoning: true }));
	});

	test("charges only the visible blocks of a turn that abandoned its tool calls", () => {
		// The replay strips every signature of a turn whose tool calls ended
		// without a tool-use stop: the model ended its turn, or max_tokens cut it.
		const toolCall = { type: "toolCall", id: "call-1", name: "read", arguments: { path: "a.ts" } } as const;
		const tokenizer = new Tokenizer(opus);
		for (const stop of ["stop", "length"] as const) {
			const turn = signedTurn(opus, VISIBLE, SIGNATURE, stop);
			turn.content = [...turn.content, toolCall];
			expect(tokenizer.countMessage(turn)).toBe(tokenizer.countMessage(turn, { excludeEncryptedReasoning: true }));
		}
		const ranTools = signedTurn(opus, VISIBLE, SIGNATURE, "toolUse");
		ranTools.content = [...ranTools.content, toolCall];
		expect(tokenizer.countMessage(ranTools)).toBe(OUTPUT_TOKENS);
	});

	test.each(["officialEndpoint", "prefixBinding"] as const)(
		"recounts another Claude model's turn when the same reader changes %s",
		field => {
			const directOpus = getBundledModel<"anthropic-messages">("anthropic", "claude-opus-5-5");
			const detached: Model<"anthropic-messages"> = {
				...directOpus,
				compat: { ...directOpus.compat, officialEndpoint: false },
				thinking: directOpus.thinking ? { ...directOpus.thinking, prefixBinding: false } : undefined,
			};
			const rebound: Model<"anthropic-messages"> =
				field === "officialEndpoint"
					? { ...detached, compat: { ...detached.compat, officialEndpoint: true } }
					: { ...detached, thinking: { ...directOpus.thinking!, prefixBinding: true } };
			const turn = signedTurn(reader("anthropic", "claude-opus-5"), VISIBLE, SIGNATURE);
			const agent = new Agent({ initialState: { model: detached, systemPrompt: [], tools: [], messages: [] } });
			const before = agent.tokenizer;
			expect(before.countMessage(turn)).toBe(VISIBLE_TOKENS);
			expect(before.countsAlike(rebound)).toBe(false);
			agent.setModel(rebound);
			expect(agent.tokenizer).not.toBe(before);
			expect(agent.tokenizer.countMessage(turn)).toBe(OUTPUT_TOKENS);
			agent.setModel(detached);
			expect(agent.tokenizer.countMessage(turn)).toBe(VISIBLE_TOKENS);
		},
	);

	test("charges the reasoning of the latest turn that abandoned its tool calls on the Claude API only", () => {
		// The Anthropic Messages replay keeps the latest assistant turn
		// byte-for-byte, signatures included; Bedrock's Converse replay strips them.
		const toolCall = { type: "toolCall", id: "call-1", name: "read", arguments: { path: "a.ts" } } as const;
		for (const stop of ["stop", "length"] as const) {
			const tokenizer = new Tokenizer(opus);
			const turn = signedTurn(opus, VISIBLE, SIGNATURE, stop);
			turn.content = [...turn.content, toolCall];
			expect(tokenizer.countLatestTurn(turn)).toBe(OUTPUT_TOKENS);
			// An older position, counted after it, still gets the stripped count.
			expect(tokenizer.countMessage(turn)).toBe(tokenizer.countMessage(turn, { excludeEncryptedReasoning: true }));

			const bedrock = new Tokenizer(bedrockOpus);
			const bedrockTurn = signedTurn(bedrockOpus, VISIBLE, SIGNATURE, stop);
			bedrockTurn.content = [...bedrockTurn.content, toolCall];
			expect(bedrock.countLatestTurn(bedrockTurn)).toBe(bedrock.countMessage(bedrockTurn));
		}
	});

	test("lowers a native Claude replay by the visible text a shake rewrite removes, after a reload too", () => {
		// The turn's output was mostly a 2,000-token code block; shake replaces it
		// in place, the reasoning still replays.
		const block = `\`\`\`\n${"x".repeat(7_992)}\n\`\`\``;
		const turn = signedTurn(opus, VISIBLE, SIGNATURE);
		turn.content = [turn.content[0], { type: "text", text: block }];
		const tokenizer = new Tokenizer(opus);
		expect(tokenizer.countMessage(turn)).toBe(OUTPUT_TOKENS);
		const entry: SessionMessageEntry = { type: "message", id: "a", parentId: null, timestamp: "", message: turn };
		applyShakeRegions(
			collectShakeRegions([entry], tokenizer, RESCUE_SHAKE_CONFIG).map(region => ({
				region,
				replacement: "[shaken]",
				replacementTokens: tokenizer.countTokens("[shaken]"),
			})),
		);
		// 3,000 output − (7 thinking + 2,000 block) visible = 993 reasoning, plus 7 + 2 visible now.
		expect(tokenizer.countMessage(turn)).toBe(993 + 7 + 2);
		// A reopened session, or a model switch, counts the saved turn in a new tokenizer.
		const saved = JSON.parse(JSON.stringify(turn)) as AssistantMessage;
		expect(new Tokenizer(opus).countMessage(saved)).toBe(993 + 7 + 2);
	});

	test("keeps the compaction floor at the visible blocks of a native Claude replay", () => {
		const model = reader("anthropic", "claude-opus-5-5");
		const floored = new Tokenizer(model).countMessage(signedTurn(model, VISIBLE, SIGNATURE), {
			excludeEncryptedReasoning: true,
		});
		expect(floored).toBe(VISIBLE_TOKENS);
	});

	test("charges the signature's bytes for a reader whose catalog prices them", () => {
		const model = reader("google", "gemini-3-pro-preview");
		expect(new Tokenizer(model).countMessage(signedTurn(model, VISIBLE, SIGNATURE))).toBe(VISIBLE_TOKENS + 1000);
	});

	// The signature is charged exactly when the request encoder keeps it: what
	// `transformMessages` (after Factory's Gemini adoption pass) leaves on the turn.
	function keptSignature(model: Model, turn: AssistantMessage): boolean {
		const history =
			model.api === "factory-droid-agent"
				? [adoptFactoryReplay(turn, model as Model<"factory-droid-agent">)]
				: [turn];
		return transformMessages(history, model).some(
			message =>
				message.role === "assistant" &&
				message.content.some(block => block.type === "thinking" && block.thinkingSignature === SIGNATURE),
		);
	}
	const gemini = reader("google", "gemini-3-pro-preview");
	// Factory serves this id on its Gemini generate wire.
	const factoryGemini = {
		...gemini,
		id: "gemini-3.8-flash",
		api: "factory-droid-agent",
		provider: "factory-droid",
	} as Model;
	const glm = getBundledModel("zai", "glm-5.3") as Model;
	test.each([
		["a Claude turn to Gemini", gemini, reader("anthropic", "claude-opus-5-5"), false],
		["another Gemini model's turn to Gemini", gemini, reader("google", "gemini-3-flash-preview"), false],
		["a Claude turn to Factory Gemini", factoryGemini, reader("anthropic", "claude-opus-5-5"), false],
		["Factory Gemini's own turn", factoryGemini, { ...factoryGemini, api: "google-generative-ai" }, true],
		["a Gemini CLI turn to Factory Gemini", factoryGemini, { ...gemini, api: "google-gemini-cli" }, true],
		["another GLM's turn to a compatible Anthropic endpoint", glm, getBundledModel("zai", "glm-5.2") as Model, true],
		[
			"a MiniMax turn to a compatible Anthropic endpoint",
			glm,
			getBundledModel("minimax", "MiniMax-M3") as Model,
			true,
		],
	] as const)("charges the signature of %s only when the request keeps it", (_case, model, from, kept) => {
		const turn = signedTurn(from, VISIBLE, SIGNATURE);
		expect(keptSignature(model, turn)).toBe(kept);
		expect(new Tokenizer(model).countMessage(turn)).toBe(VISIBLE_TOKENS + (kept ? 1000 : 0));
		expect(new Tokenizer(model).countMessage(turn, { excludeEncryptedReasoning: true })).toBe(VISIBLE_TOKENS);
	});
});

// Contract: an assistant turn's native Responses history replays its reasoning
// items only to the api, model and provider that produced it, and Codex bills
// each replayed turn at that turn's reported reasoning tokens. The ciphertext
// is not that price (it runs ~3x larger), and reasoning that is not replayed,
// or that replay drops with its turn, costs nothing.
describe("replayed Responses reasoning", () => {
	const sol = bundledModel<"openai-codex-responses">("openai-codex", "gpt-6.1-sol");
	const otherCodex = bundledModel<"openai-codex-responses">("openai-codex", "gpt-6-sol");
	const REASONING_TOKENS = 5_000;
	const reasoningItem = { type: "reasoning", id: "rs_1", summary: [], encrypted_content: "e".repeat(16_000) };
	const callItem = { type: "function_call", call_id: "call_1", name: "read", arguments: '{"path":"a.ts"}' };
	const emptyAnswerItem = {
		type: "message",
		role: "assistant",
		content: [{ type: "output_text", text: "", annotations: [] }],
	};
	// Replayable native output a thinking-only turn can still carry.
	const searchItem = {
		type: "web_search_call",
		id: "ws_1",
		status: "completed",
		action: { type: "search", query: "q" },
	};
	const signedThinking = { type: "thinking", thinking: "", thinkingSignature: JSON.stringify(reasoningItem) } as const;
	const toolCall = { type: "toolCall", id: "call_1", name: "read", arguments: { path: "a.ts" } } as const;
	const floored = { excludeEncryptedReasoning: true } as const;

	function responsesTurn(
		model: Model,
		payload: AssistantMessage["providerPayload"],
		content: AssistantMessage["content"] = [signedThinking, toolCall],
		stopReason: AssistantMessage["stopReason"] = "toolUse",
	): AssistantMessage {
		return {
			role: "assistant",
			api: model.api,
			provider: model.provider,
			model: model.id,
			content,
			providerPayload: payload,
			usage: {
				input: 0,
				output: 6_000,
				cacheRead: 0,
				cacheWrite: 0,
				totalTokens: 6_000,
				reasoningTokens: REASONING_TOKENS,
				cost: { input: 0, output: 0, cacheRead: 0, cacheWrite: 0, total: 0 },
			},
			stopReason,
			timestamp: 0,
		};
	}
	const codexTurn = (payload: AssistantMessage["providerPayload"], signed = true): AssistantMessage =>
		responsesTurn(sol, payload, [signed ? signedThinking : { type: "thinking", thinking: "" }, toolCall]);
	const history = (
		provider: string,
		items: Array<Record<string, unknown>> = [reasoningItem, callItem],
	): AssistantMessage["providerPayload"] => ({ type: "openaiResponsesHistory", provider, dt: true, items });
	const replayed = (provider: string = sol.provider) => history(provider);
	const visibleTokens = (tokenizer: Tokenizer) => tokenizer.countMessage(codexTurn(undefined, false));
	/** Reasoning items the real Codex request carries for `turn`. */
	const wireReasoning = (turn: AssistantMessage) =>
		convertCodexResponsesMessages(sol, { messages: [turn] }).filter(item => item.type === "reasoning").length;

	test("charges the turn's reported reasoning tokens, not its ciphertext, to the model it replays to", () => {
		const tokenizer = new Tokenizer(sol);
		const expected = visibleTokens(tokenizer) + REASONING_TOKENS;
		expect(tokenizer.countMessage(codexTurn(replayed()))).toBe(expected);
		// The provider's own count is a token price, so the stored-context floor keeps it too.
		expect(tokenizer.countMessage(codexTurn(replayed()), floored)).toBe(expected);
	});

	test("charges nothing for reasoning that does not replay to the reader", () => {
		const tokenizer = new Tokenizer(sol);
		// Control: the reader that produced the turn is charged.
		expect(tokenizer.countMessage(codexTurn(replayed()), floored)).toBe(visibleTokens(tokenizer) + REASONING_TOKENS);
		// Minted for another provider, or carrying no reasoning item: nothing replays.
		expect(tokenizer.countMessage(codexTurn(replayed("openai")), floored)).toBe(visibleTokens(tokenizer));
		expect(tokenizer.countMessage(codexTurn(history(sol.provider, [callItem])), floored)).toBe(
			visibleTokens(tokenizer),
		);
		// Another model on the same provider gets the turn re-encoded without its reasoning.
		const other = new Tokenizer(otherCodex);
		expect(other.countMessage(codexTurn(replayed()), floored)).toBe(visibleTokens(other));
	});

	test("charges nothing to a reader that filters reasoning history out of its requests", () => {
		const openai = bundledModel<"openai-responses">("openai", "gpt-6.1-sol");
		const turn = responsesTurn(openai, history(openai.provider));
		const visible = (tokenizer: Tokenizer) =>
			tokenizer.countMessage(responsesTurn(openai, undefined, [{ type: "thinking", thinking: "" }, toolCall]));
		const replaying = new Tokenizer(openai);
		expect(replaying.countMessage(turn, floored)).toBe(visible(replaying) + REASONING_TOKENS);
		const filtering = new Tokenizer({ ...openai, compat: { ...openai.compat, filterReasoningHistory: true } });
		expect(filtering.countMessage(turn, floored)).toBe(visible(filtering));
	});

	test("charges nothing, signature included, for a turn whose replay sends no reasoning", () => {
		const tokenizer = new Tokenizer(sol);
		const dropped: Array<[string, AssistantMessage]> = [
			// The sanitizer turns these native payloads into nothing replayable.
			[
				"hidden-empty",
				responsesTurn(
					sol,
					history(sol.provider, [reasoningItem, emptyAnswerItem]),
					[signedThinking, { type: "text", text: "" }],
					"stop",
				),
			],
			["reasoning-only", responsesTurn(sol, history(sol.provider, [reasoningItem]), [signedThinking], "stop")],
			// transformMessages drops thinking-only turns that were cut off, even
			// when their native items would otherwise replay.
			...(["length", "error", "aborted"] as const).map((stopReason): [string, AssistantMessage] => [
				`thinking-only ${stopReason}`,
				responsesTurn(sol, history(sol.provider, [reasoningItem, searchItem]), [signedThinking], stopReason),
			]),
		];
		for (const [name, turn] of dropped) {
			expect({ name, wire: wireReasoning(turn) }).toEqual({ name, wire: 0 });
			// Nothing of the turn reaches the wire: no reasoning price, no signature bytes.
			expect({ name, count: tokenizer.countMessage(turn) }).toEqual({ name, count: 0 });
			expect({ name, floor: tokenizer.countMessage(turn, floored) }).toEqual({ name, floor: 0 });
		}
		// Controls: the same items replay when the turn finished, and reasoning
		// ahead of a tool call replays even when the turn was cut off.
		const finished = responsesTurn(sol, history(sol.provider, [reasoningItem, searchItem]), [signedThinking], "stop");
		expect(wireReasoning(finished)).toBe(1);
		expect(tokenizer.countMessage(finished, floored)).toBe(REASONING_TOKENS);
		const cutOffCall = responsesTurn(sol, replayed(), [signedThinking, toolCall], "length");
		expect(wireReasoning(cutOffCall)).toBe(1);
		expect(tokenizer.countMessage(cutOffCall, floored)).toBe(visibleTokens(tokenizer) + REASONING_TOKENS);
	});

	test("an Agent recounts replayed reasoning after switching to a model it does not replay to", () => {
		const agent = new Agent({ initialState: { model: sol, systemPrompt: [], tools: [], messages: [] } });
		const turn = codexTurn(replayed());
		expect(agent.tokenizer.countMessage(turn, floored)).toBe(visibleTokens(agent.tokenizer) + REASONING_TOKENS);
		agent.setModel(otherCodex);
		expect(agent.tokenizer.countMessage(turn, floored)).toBe(visibleTokens(agent.tokenizer));
	});

	test("prices a replayed turn whose backend reported no reasoning tokens at its signature", () => {
		const unreported = codexTurn(replayed());
		delete unreported.usage.reasoningTokens;
		// The reasoning item still goes on the wire, so the turn is not free.
		expect(wireReasoning(unreported)).toBe(1);
		const tokenizer = new Tokenizer(sol);
		// Its only price is the ciphertext, counted as text.
		expect(tokenizer.countMessage(unreported)).toBe(
			visibleTokens(tokenizer) + tokenizer.countTokens(JSON.stringify(reasoningItem)),
		);
		expect(tokenizer.countMessage(unreported, floored)).toBe(visibleTokens(tokenizer));
		// Another model re-encodes the turn without its reasoning: neither price applies.
		const reencoding = new Tokenizer(otherCodex);
		expect(reencoding.countMessage(unreported)).toBe(visibleTokens(reencoding));
	});

	test("follows a cold Responses session, which rebuilds encrypted reasoning out of the request", async () => {
		const copilot = getBundledModel<"openai-responses">("github-copilot", "gpt-5.4");
		const encrypted = responsesTurn(copilot, history(copilot.provider));
		// Plaintext reasoning bound to no server state replays natively even cold.
		const plaintext = responsesTurn(
			copilot,
			history(copilot.provider, [
				{ type: "reasoning", summary: [], content: [{ type: "reasoning_text", text: "Reasoning." }] },
				callItem,
			]),
		);
		const visible = (tokenizer: Tokenizer) =>
			tokenizer.countMessage(responsesTurn(copilot, undefined, [{ type: "thinking", thinking: "" }, toolCall]));
		const providerSessionState = new Map<string, ProviderSessionState>();
		const agent = new Agent({
			initialState: { model: copilot, systemPrompt: [], tools: [], messages: [] },
			providerSessionState,
		});
		const observe = async () => ({
			wire: await responsesWireReasoning(copilot, encrypted, providerSessionState),
			count: agent.tokenizer.countMessage(encrypted),
			floor: agent.tokenizer.countMessage(encrypted, floored),
		});

		const cold = await observe();
		expect(cold).toEqual({ wire: 0, count: visible(agent.tokenizer), floor: visible(agent.tokenizer) });
		expect(await responsesWireReasoning(copilot, plaintext, providerSessionState)).toBe(1);
		expect(agent.tokenizer.countMessage(plaintext, floored)).toBe(visible(agent.tokenizer) + REASONING_TOKENS);
		// The first successful response warms the session (as the provider does).
		for (const state of providerSessionState.values()) {
			(state as ProviderSessionState & { nativeHistoryReplayWarmed: boolean }).nativeHistoryReplayWarmed = true;
		}
		const warm = visible(agent.tokenizer) + REASONING_TOKENS;
		expect(await observe()).toEqual({ wire: 1, count: warm, floor: warm });
		for (const state of providerSessionState.values()) state.close();
		expect(await observe()).toEqual(cold);
	});
});

function bundledModel<TApi extends Api = Api>(provider: "openai" | "openai-codex", id: string): Model<TApi> {
	const model = getBundledModel<TApi>(provider, id);
	if (!model) throw new Error(`Expected bundled ${provider}/${id}`);
	return model;
}

/** Reasoning items the real Responses request carries for `turn` under the session's replay state. */
async function responsesWireReasoning(
	model: Model<"openai-responses">,
	turn: AssistantMessage,
	providerSessionState: Map<string, ProviderSessionState>,
): Promise<number> {
	const { promise, resolve } = Promise.withResolvers<unknown>();
	const controller = new AbortController();
	controller.abort();
	const messages = [
		{ role: "user" as const, content: "Question?", timestamp: 0 },
		turn,
		{ role: "user" as const, content: "Next.", timestamp: 0 },
	];
	streamOpenAIResponses(
		model,
		{ messages },
		{ apiKey: "test-key", signal: controller.signal, providerSessionState, onPayload: resolve },
	);
	const { input } = (await promise) as { input: Array<{ type?: string }> };
	return input.filter(item => item.type === "reasoning").length;
}

/** The per-image charge, read back through the arm that already applied it. */
function inToolResultImageEstimate(tokenizer: Tokenizer): number {
	return tokenizer.countMessage({
		role: "toolResult",
		toolCallId: "call-probe",
		toolName: "read",
		content: [{ type: "image", data: "A".repeat(40_000), mimeType: "image/png" }],
		isError: false,
		timestamp: 0,
	} as unknown as AgentMessage);
}

/**
 * OMP Browser Relay — MV3 service worker.
 *
 * Dumb pipe by design: all CDP orchestration lives in the relay server. This
 * worker (1) keeps a websocket to the relay, (2) executes its RPCs against
 * `chrome.debugger`/`chrome.tabs`, and (3) streams tab + debugger events back.
 *
 * Service-worker lifetime: the open websocket plus a periodic ping keeps the
 * worker alive while connected (Chrome 116+); a chrome.alarms tick revives it
 * and re-dials after Chrome reaps it while disconnected. Each dial probes the
 * port with a fetch first: a refused WebSocket is logged into the extension's
 * error list by Chrome's network layer on every attempt, a refused fetch is not.
 */
import {
	EXTENSION_RELOAD_PROTOCOL_VERSION,
	type ExtToRelayMessage,
	type RelayToExtMessage,
	type TabSnapshot,
} from "../../coding-agent/src/tools/browser/relay/protocol";
import { ownedDebuggerTabs } from "./debugger-ownership";

import { ScreenshotCapture } from "./screenshot-capture";

const screenshotCapture = new ScreenshotCapture(
	(target, method, params) => chrome.debugger.sendCommand(target, method, params),
	async tabId => {
		const tab = await chrome.tabs.get(tabId);
		return (await chrome.windows.get(tab.windowId)).state === "minimized";
	},
);

const DEFAULT_PORT = 9224;
const PING_INTERVAL_MS = 20_000;
const RECONNECT_MIN_MS = 1_000;
const RECONNECT_MAX_MS = 10_000;
const PROBE_TIMEOUT_MS = 2_000;
const REMOVE_TAB_ATTEMPTS = 3;
const REMOVE_TAB_RETRY_MS = 500;

/**
 * The omp version that installed this script, declared by the line the installer puts above it
 * (`stampRelayExtensionScript`); undeclared in an unstamped build. Read from the script, not the manifest:
 * after the files change, a Chrome restart re-reads manifest.json but keeps running the old service worker.
 */
declare const OMP_INSTALL_VERSION: string | undefined;

let ws: WebSocket | null = null;
let reconnectDelay = RECONNECT_MIN_MS;
let reconnectTimer: NodeJS.Timeout | null = null;
let dialing = false;
let pingTimer: NodeJS.Timeout | null = null;
const relayInitiatedDetachTabs = new Set<number>();

/**
 * Tab ids this extension created for omp (`createTab`), reported in hello as
 * `ownedTabIds`. The relay's orphan reaper closes only these, so a record left
 * by a crashed omp session can never close a user tab. `chrome.storage.session`
 * survives service-worker restarts and is cleared with the browser session,
 * exactly when Chrome starts reusing tab ids.
 */
const CREATED_TABS_KEY = "ompCreatedTabIds";
let createdTabs: Promise<Set<number>> | null = null;
function loadCreatedTabs(): Promise<Set<number>> {
	createdTabs ??= chrome.storage.session
		.get({ [CREATED_TABS_KEY]: [] })
		.then(stored => {
			const raw = stored[CREATED_TABS_KEY];
			return new Set(Array.isArray(raw) ? raw.filter((id): id is number => typeof id === "number") : []);
		})
		.catch(() => new Set<number>());
	return createdTabs;
}

async function markCreatedTab(tabId: number, created: boolean): Promise<void> {
	const ids = await loadCreatedTabs();
	if (created === ids.has(tabId)) return;
	if (created) ids.add(tabId);
	else ids.delete(tabId);
	await chrome.storage.session.set({ [CREATED_TABS_KEY]: [...ids] }).catch(() => {});
}

/**
 * Stable per-install browser identity, persisted in `chrome.storage.local` and
 * sent in every hello. The relay namespaces tab registries per instance, so
 * several browsers can share one relay and a service-worker restart keeps the
 * browser's tab registry instead of replacing another browser's connection.
 */
let instanceId: string | null = null;
async function ensureInstanceId(): Promise<string> {
	if (instanceId) return instanceId;
	const key = "relayInstanceId";
	const stored = await chrome.storage.local.get({ [key]: "" });
	const existing = stored[key];
	instanceId = typeof existing === "string" && existing.length > 0 ? existing : crypto.randomUUID();
	await chrome.storage.local.set({ [key]: instanceId } as Record<string, string>);
	return instanceId;
}

/**
 * Identity of this browser run, in `chrome.storage.session`. Chrome clears it on restart, when it also reuses tab
 * ids, so the relay retires the previous run's targets instead of resolving an old target id to a new tab. An
 * extension reload clears it too: omp then loses its handles to the tabs it opened, which stay open.
 */
let browserSession: Promise<string> | null = null;
function ensureBrowserSession(): Promise<string> {
	browserSession ??= (async () => {
		const key = "relayBrowserSession";
		const stored = await chrome.storage.session.get({ [key]: "" });
		const existing = stored[key];
		if (typeof existing === "string" && existing.length > 0) return existing;
		const created = crypto.randomUUID();
		await chrome.storage.session.set({ [key]: created } as Record<string, string>);
		return created;
	})();
	return browserSession;
}

interface RelaySettings {
	port: number;
	token: string;
}

async function loadSettings(): Promise<RelaySettings> {
	const stored = await chrome.storage.local.get({ port: DEFAULT_PORT, token: "" });
	const port = Number(stored.port);
	return {
		port: Number.isInteger(port) && port > 0 && port <= 65535 ? port : DEFAULT_PORT,
		token: typeof stored.token === "string" ? stored.token : "",
	};
}

function snapshot(tab: ChromeTab): TabSnapshot | null {
	if (tab.id === undefined) return null;
	return {
		tabId: tab.id,
		url: tab.url ?? tab.pendingUrl ?? "",
		title: tab.title ?? "",
		active: tab.active,
		discarded: tab.discarded === true,
		windowId: tab.windowId,
		pinned: tab.pinned,
		groupId: tab.groupId,
	};
}

/**
 * Serialize group mutations. Chrome's query→group→set-title sequence is not
 * atomic: two concurrent runs both miss the not-yet-titled group and mint
 * duplicate "omp" groups in the same window.
 */
let groupOps: Promise<unknown> = Promise.resolve();
function enqueueGroupOp<T>(fn: () => Promise<T>): Promise<T> {
	const result = groupOps.then(fn, fn);
	groupOps = result.catch(() => {});
	return result;
}

/** Move tabs into their named per-window omp session group, creating or reusing it by title. */
async function groupTabs(tabIds: number[], title: string, color: string): Promise<{ grouped: Record<string, number> }> {
	const byWindow = new Map<number, number[]>();
	for (const tabId of tabIds) {
		try {
			const tab = await chrome.tabs.get(tabId);
			// Grouping silently unpins; never touch pinned tabs.
			if (tab.pinned || tab.id === undefined) continue;
			const bucket = byWindow.get(tab.windowId) ?? [];
			bucket.push(tab.id);
			byWindow.set(tab.windowId, bucket);
		} catch {
			// Tab already closed.
		}
	}
	const grouped: Record<string, number> = {};
	for (const [windowId, ids] of byWindow) {
		const existing = await chrome.tabGroups.query({ title, windowId });
		let groupId: number;
		if (existing[0]) {
			groupId = existing[0].id;
			// Heal duplicate same-title groups left behind by older races.
			for (const dupe of existing.slice(1)) {
				const dupeTabs = await chrome.tabs.query({ groupId: dupe.id });
				const dupeIds = dupeTabs.map(tab => tab.id).filter(id => id !== undefined);
				if (dupeIds.length > 0) await chrome.tabs.group({ tabIds: dupeIds, groupId });
			}
			await chrome.tabs.group({ tabIds: ids, groupId });
		} else {
			groupId = await chrome.tabs.group({ tabIds: ids });
		}
		await chrome.tabGroups.update(groupId, { title, color });
		for (const id of ids) grouped[String(id)] = groupId;
	}
	return { grouped };
}

/** Dissolve all omp session groups when the relay disconnects. */
async function restoreGroups(): Promise<void> {
	const groups = await chrome.tabGroups.query({}).catch(() => []);
	for (const group of groups) {
		if (group.title !== "omp" && !group.title?.startsWith("omp/")) continue;
		const tabs = await chrome.tabs.query({ groupId: group.id }).catch(() => []);
		const ids = tabs.map(tab => tab.id).filter(id => id !== undefined);
		if (ids.length > 0) await chrome.tabs.ungroup(ids).catch(() => {});
	}
}

function post(msg: ExtToRelayMessage): void {
	if (ws?.readyState === WebSocket.OPEN) ws.send(JSON.stringify(msg));
}

/** Chrome can refuse a tab close for a moment (a tab being dragged, an unload in progress); try again before failing. */
async function removeTab(tabId: number): Promise<void> {
	for (let attempt = 1; ; attempt++) {
		try {
			await chrome.tabs.remove(tabId);
			return;
		} catch (error) {
			// Already closed: the close the relay asked for has happened.
			if (/No tab with id/.test(String(error))) return;
			if (attempt >= REMOVE_TAB_ATTEMPTS) throw error;
			const pause = Promise.withResolvers<void>();
			setTimeout(pause.resolve, REMOVE_TAB_RETRY_MS);
			await pause.promise;
		}
	}
}

async function setBadge(connected: boolean): Promise<void> {
	try {
		await chrome.action.setBadgeText({ text: connected ? "on" : "off" });
		await chrome.action.setBadgeBackgroundColor({ color: connected ? "#1a7f37" : "#8b8b8b" });
	} catch {
		// Badge is cosmetic; never let it break the relay loop.
	}
}

async function buildHello(): Promise<ExtToRelayMessage> {
	const [tabs, targets, created] = await Promise.all([
		chrome.tabs.query({}),
		chrome.debugger.getTargets(),
		loadCreatedTabs(),
	]);
	const snapshots: TabSnapshot[] = [];
	for (const tab of tabs) {
		const snap = snapshot(tab);
		if (snap) snapshots.push(snap);
	}
	// `attached` is true for DevTools or another extension too; only our own attachment answers a command.
	const attachedTabIds = await ownedDebuggerTabs(targets, tabId =>
		chrome.debugger.sendCommand({ tabId }, "Target.getTargetInfo"),
	);
	const versionMatch = /Chrome\/[\d.]+/.exec(navigator.userAgent);
	return {
		t: "hello",
		instanceId: await ensureInstanceId(),
		browserSession: await ensureBrowserSession(),
		userAgent: navigator.userAgent,
		browserVersion: versionMatch?.[0] ?? "Chrome/unknown",
		discardedTabsProtocol: 1, // Keep in sync with the relay protocol version.
		ompVersion: typeof OMP_INSTALL_VERSION === "string" ? OMP_INSTALL_VERSION : undefined,
		reloadProtocol: EXTENSION_RELOAD_PROTOCOL_VERSION,
		tabs: snapshots,
		attachedTabIds,
		ownedTabIds: snapshots.filter(snap => created.has(snap.tabId)).map(snap => snap.tabId),
	};
}

/**
 * Window for a new background tab. Without an explicit `windowId`,
 * `chrome.tabs.create` rejects with "No current window" whenever every Chrome
 * window is minimized; prefer the focused window, then a visible one, then any
 * normal window (a minimized window still accepts tabs without restoring it).
 */
async function tabWindowId(): Promise<number | undefined> {
	const windows = await chrome.windows.getAll({ windowTypes: ["normal"] });
	const chosen =
		windows.find(window => window.focused) ??
		windows.find(window => window.state !== "minimized") ??
		windows[0];
	return chosen?.id;
}

/** Run one relay RPC; `origin` is the socket it came in on, which alone can carry its answer. */
async function runRpc(msg: Extract<RelayToExtMessage, { t: "rpc" }>, origin: WebSocket): Promise<unknown> {
	switch (msg.op) {
		case "attach":
			await chrome.debugger.attach({ tabId: msg.tabId }, "1.3");
			return {};
		case "detach":
			relayInitiatedDetachTabs.add(msg.tabId);
			try {
				await chrome.debugger.detach({ tabId: msg.tabId });
				return {};
			} catch (error) {
				relayInitiatedDetachTabs.delete(msg.tabId);
				throw error;
			}
		case "send":
			return await screenshotCapture.send(
				msg.sessionId ? { tabId: msg.tabId, sessionId: msg.sessionId } : { tabId: msg.tabId },
				msg.method,
				msg.params,
			);
		case "createTab": {
			// Keep automatic relay tabs in the background; only an explicit RPC override may select them.
			const tab = await chrome.tabs.create({ url: msg.url, active: msg.active ?? false, windowId: await tabWindowId() });
			const snap = snapshot(tab);
			if (!snap) throw new Error("created tab has no id");
			await markCreatedTab(snap.tabId, true);
			// The relay failed this call when its socket closed, so nobody learns this tab's id to close it later.
			if (origin.readyState !== WebSocket.OPEN) void removeTab(snap.tabId).catch(() => {});
			return { tab: snap };
		}
		case "removeTab":
			await removeTab(msg.tabId);
			return {};
		case "activateTab": {
			const tab = await chrome.tabs.get(msg.tabId);
			await chrome.windows.update(tab.windowId, { focused: true });
			await chrome.tabs.update(msg.tabId, { active: true });
			return {};
		}
		case "group":
			return await enqueueGroupOp(() => groupTabs(msg.tabIds, msg.title, msg.color));
		case "ungroup":
			await enqueueGroupOp(() => chrome.tabs.ungroup(msg.tabIds).catch(() => {}));
			return {};
	}
}

function handleRelayMessage(socket: WebSocket, raw: string): void {
	let msg: RelayToExtMessage;
	try {
		msg = JSON.parse(raw) as RelayToExtMessage;
	} catch {
		return;
	}
	if (msg.t === "pong") return;
	if (msg.t === "reload") {
		// The relay rewrote this extension's files; reloading re-reads them (a Chrome restart would not).
		chrome.runtime.reload();
		return;
	}
	// Answer only on the socket the RPC came in on: RPC ids are local to that connection, and the relay already
	// failed the call when it closed.
	const answer = (reply: ExtToRelayMessage): void => {
		if (socket.readyState === WebSocket.OPEN) socket.send(JSON.stringify(reply));
	};
	void runRpc(msg, socket)
		.then(result => answer({ t: "rpcResult", id: msg.id, ok: true, result }))
		.catch((err: unknown) => {
			answer({ t: "rpcResult", id: msg.id, ok: false, error: err instanceof Error ? err.message : String(err) });
		});
}

/** Single retry timer: alarm-driven dials must not each start another backoff chain. */
function scheduleReconnect(): void {
	if (reconnectTimer !== null) return;
	const delay = reconnectDelay;
	reconnectDelay = Math.min(reconnectDelay * 2, RECONNECT_MAX_MS);
	reconnectTimer = setTimeout(() => {
		reconnectTimer = null;
		void connect();
	}, delay);
}

/** True when something answers HTTP on the relay port; a refused fetch leaves no extension error entry. */
async function relayListening(port: number): Promise<boolean> {
	try {
		await fetch(`http://127.0.0.1:${port}/json/version`, {
			mode: "no-cors",
			cache: "no-store",
			signal: AbortSignal.timeout(PROBE_TIMEOUT_MS),
		});
		return true;
	} catch {
		return false;
	}
}

async function connect(): Promise<void> {
	if (dialing || (ws && (ws.readyState === WebSocket.OPEN || ws.readyState === WebSocket.CONNECTING))) return;
	dialing = true;
	try {
		const settings = await loadSettings();
		if (!(await relayListening(settings.port))) {
			scheduleReconnect();
			return;
		}
		const url = `ws://127.0.0.1:${settings.port}/ext${settings.token ? `?token=${encodeURIComponent(settings.token)}` : ""}`;
		const socket = new WebSocket(url);
		ws = socket;
		socket.onopen = () => {
			reconnectDelay = RECONNECT_MIN_MS;
			void setBadge(true);
			void buildHello().then(hello => post(hello));
			clearInterval(pingTimer ?? undefined);
			pingTimer = setInterval(() => post({ t: "ping" }), PING_INTERVAL_MS);
		};
		socket.onmessage = event => {
			if (typeof event.data === "string") handleRelayMessage(socket, event.data);
		};
		socket.onclose = () => {
			if (ws !== socket) return;
			ws = null;
			if (pingTimer !== null) {
				clearInterval(pingTimer);
				pingTimer = null;
			}
			void setBadge(false);
			void enqueueGroupOp(restoreGroups);
			scheduleReconnect();
		};
		socket.onerror = () => {
			socket.close();
		};
	} finally {
		dialing = false;
	}
}

// ---- event streaming ---------------------------------------------------------

chrome.debugger.onEvent.addListener((source, method, params) => {
	if (source.tabId === undefined) return;
	const target = { tabId: source.tabId, sessionId: source.sessionId };
	if (screenshotCapture.handleEvent(target, method, params)) return;
	if (method === "Target.detachedFromTarget" && typeof params?.sessionId === "string") {
		screenshotCapture.detach({ tabId: source.tabId, sessionId: params.sessionId });
	}
	post({ t: "cdpEvent", tabId: source.tabId, sessionId: source.sessionId, method, params });
});

chrome.debugger.onDetach.addListener((source, reason) => {
	if (source.tabId === undefined) return;
	screenshotCapture.detach({ tabId: source.tabId });
	const relayInitiated = relayInitiatedDetachTabs.delete(source.tabId);
	post({ t: "detached", tabId: source.tabId, reason, relayInitiated });
});

chrome.tabs.onCreated.addListener(tab => {
	const snap = snapshot(tab);
	if (snap) post({ t: "tabCreated", tab: snap });
});

chrome.tabs.onUpdated.addListener((_tabId, _changeInfo, tab) => {
	const snap = snapshot(tab);
	if (snap) post({ t: "tabUpdated", tab: snap });
});

chrome.tabs.onActivated.addListener(({ tabId }) => {
	void chrome.tabs.get(tabId).then(tab => {
		const snap = snapshot(tab);
		if (snap) post({ t: "tabUpdated", tab: snap });
	}).catch(() => {
		// The tab may have closed before Chrome answered.
	});
});

chrome.tabs.onRemoved.addListener(tabId => {
	screenshotCapture.detach({ tabId });
	void markCreatedTab(tabId, false);
	post({ t: "tabRemoved", tabId });
});

// ---- lifecycle ----------------------------------------------------------------

chrome.alarms.create("omp-relay-keepalive", { periodInMinutes: 0.5 });
chrome.alarms.onAlarm.addListener(alarm => {
	if (alarm.name === "omp-relay-keepalive") void connect();
});

chrome.storage.onChanged.addListener((_changes, areaName) => {
	if (areaName !== "local") return;
	// Settings changed: drop the current connection and re-dial with new ones.
	ws?.close();
	void connect();
});

chrome.action.onClicked.addListener(() => {
	// A click is also a cheap way to re-dial a relay that just came up.
	void connect();
	void chrome.runtime.openOptionsPage();
});
chrome.runtime.onInstalled.addListener(() => void connect());
chrome.runtime.onStartup.addListener(() => void connect());

void connect();

