	enableMCP?: boolean;
	/** Kernel-defined tools explicitly exposed by the parent eval session. */
	customTools?: CustomTool[];
	/** Workpool items accepted by the child yield tool during this turn. */
	workPoolYieldItems?: WorkPoolYieldItem[];
