	invokedAt?: number;
	acquiredAt?: number;
	sessionFile?: string | null;
	persistArtifacts?: boolean;
	artifactsDir?: string;
	eventBus?: EventBus;
	subagentEventBus?: EventBus;
	contextFiles?: ContextFileEntry[];
	noContextFiles?: boolean;
