	compactionThresholdOverride?: CompactionThresholdPair;
	/** Exact-name `task.agentAccountPools` entry selected by dispatch; see `CreateAgentSessionOptions.oauthAccountPools`. */
	oauthAccountPools?: OAuthAccountPools;
