      if (state.owner === "recording")
        state.owner = undefined;
      return result;
    }
    if (state.owner === "recording" || !await this.isMinimized(state.target.tabId)) {
      if (state.detached)
        throw new Error("Screenshot target detached");
      return await this.sendCommand(state.target, method, params);
    }
    if (state.detached)
      throw new Error("Screenshot target detached");
    state.owner = "temporary";
    state.temporaryActive = true;
    try {
      await this.sendCommand(state.target, "Page.startScreencast", { format: "png", everyNthFrame: 1 });
      if (state.detached)
        throw new Error("Screenshot target detached");
      return await this.sendCommand(state.target, method, params);
    } finally {
      await this.#stopTemporary(state);
    }
  }
  handleEvent(target, method, params) {
    if (method !== "Page.screencastFrame" || this.#states.get(this.#key(target))?.owner !== "temporary") {
      return false;
    }
    if (typeof params?.sessionId === "number") {
      this.sendCommand(target, "Page.screencastFrameAck", { sessionId: params.sessionId }).catch(() => {});
    }
    return true;
  }
  detach(target) {
    for (const [key, state] of this.#states) {
      if (state.target.tabId !== target.tabId)
        continue;
      if (target.sessionId !== undefined && state.target.sessionId !== target.sessionId)
        continue;
      state.detached = true;
      this.#states.delete(key);
    }
  }
}

