			const answer = Promise.withResolvers<void>();
			const server = Bun.serve({
				port: 0,
				async fetch() {
					requested.resolve();
					await answer.promise;
					return new Response("<title>late</title>", { headers: { "content-type": "text/html" } });
				},
			});
			const url = server.url.href;
