describe("RelayBridge download paths", () => {
	function hello(bridge: RelayBridge, socket: FakeExtSocket, downloadsProtocol?: number): void {
		bridge.extConnected(socket);
		bridge.extMessage(
			socket,
			JSON.stringify({
				t: "hello",
				userAgent: "test",
				browserVersion: "Chrome/151.0.0.0",
				discardedTabsProtocol: 1,
				downloadsProtocol,
				tabs: [tab({ tabId: 1 })],
				attachedTabIds: [],
			}),
		);
	}

	async function askPath(bridge: RelayBridge, ext: FakeExtSocket): Promise<{ cdp: FakeCdpSocket; id: number }> {
		const cdp = new FakeCdpSocket();
		const connId = bridge.cdpConnected(cdp);
		const sessionId = await attachPage(bridge, ext, cdp, connId, 1);
		const id = ++msgSeq;
		bridge.cdpMessage(
			connId,
			JSON.stringify({ id, sessionId, method: "OMP.downloadPath", params: { guid: "guid-1" } }),
		);
		await flush();
		return { cdp, id };
	}

	it.each([undefined, 1])("rejects download lookup even when the peer advertises protocol %s", async protocol => {
		const bridge = new RelayBridge({});
		const ext = new FakeExtSocket();
		hello(bridge, ext, protocol);
		const { cdp, id } = await askPath(bridge, ext);
		expect(ext.messages.some(message => "op" in message && String(message.op) === "findDownload")).toBe(false);
		expect(ext.rpcs("send").some(rpc => rpc.method === "OMP.downloadPath")).toBe(false);
		expect(cdp.messages.find(m => m.id === id)).toMatchObject({
			error: { message: "Relay download tracking is unavailable under this fork's existing extension permissions" },
		});
	});
});

